export function validateST_TextScaleDecimal(value: unknown, path = 'ST_TextScaleDecimal'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (typeof value !== 'number' || !Number.isFinite(value)) issues.push(issue(path, 'invalid-value', 'expected a finite number'));
  if (typeof value === 'number' && value < 0) issues.push(issue(path, 'facet-violation', 'below minInclusive'));
  if (typeof value === 'number' && value > 600) issues.push(issue(path, 'facet-violation', 'above maxInclusive'));
  return issues;
}

export function validateST_TextScalePercent(value: unknown, path = 'ST_TextScalePercent'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (typeof value !== 'string') issues.push(issue(path, 'invalid-value', 'expected a string'));
  if (typeof value === 'string' && !(new RegExp("0*(600|([0-5]?[0-9]?[0-9]))%")).test(value)) issues.push(issue(path, 'facet-violation', 'pattern mismatch'));
  return issues;
}

