export function validateCT_FFCheckBox(value: unknown, path = 'CT_FFCheckBox'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (value === null || typeof value !== 'object') return [issue(path, 'invalid-value', 'expected an object')];
  const v = value as Record<string, unknown>;
  if (v['content'] === undefined) {
    issues.push(issue(path + '.content', 'missing-required', 'required slot is absent'));
  } else {
    if (v['content'] && typeof v['content'] === 'object') {
      const item = v['content'] as { kind?: unknown; value?: unknown };
      if (item.kind !== '$raw') {
        if (item.kind === 'size') issues.push(...validateCT_HpsMeasure(item.value, path + '.content' + '.value'));
        if (item.kind === 'sizeAuto') issues.push(...validateCT_OnOff(item.value, path + '.content' + '.value'));
        if ('size' !== item.kind && 'sizeAuto' !== item.kind) issues.push(issue(path + '.content', 'invalid-value', 'unknown choice alternative'));
      }
    }
  }
  if (v['default'] === undefined) {
  } else {
    issues.push(...validateCT_OnOff(v['default'], path + '.default'));
  }
  if (v['checked'] === undefined) {
  } else {
    issues.push(...validateCT_OnOff(v['checked'], path + '.checked'));
  }
  return issues;
}

