export function validateCT_FFData(value: unknown, path = 'CT_FFData'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (value === null || typeof value !== 'object') return [issue(path, 'invalid-value', 'expected an object')];
  const v = value as Record<string, unknown>;
  if (!Array.isArray(v['content'])) {
  } else {
    for (let i = 0; i < (v['content'] as readonly unknown[]).length; i += 1) {
      if ((v['content'] as readonly unknown[])[i] && typeof (v['content'] as readonly unknown[])[i] === 'object') {
        const item = (v['content'] as readonly unknown[])[i] as { kind?: unknown; value?: unknown };
        if (item.kind !== '$raw') {
          if (item.kind === 'name') issues.push(...validateCT_FFName(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'label') issues.push(...validateCT_DecimalNumber(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'tabIndex') issues.push(...validateCT_UnsignedDecimalNumber(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'enabled') issues.push(...validateCT_OnOff(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'calcOnExit') issues.push(...validateCT_OnOff(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'entryMacro') issues.push(...validateCT_MacroName(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'exitMacro') issues.push(...validateCT_MacroName(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'helpText') issues.push(...validateCT_FFHelpText(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'statusText') issues.push(...validateCT_FFStatusText(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'checkBox') issues.push(...validateCT_FFCheckBox(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'ddList') issues.push(...validateCT_FFDDList(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'textInput') issues.push(...validateCT_FFTextInput(item.value, path + '.content[' + i + ']' + '.value'));
          if ('name' !== item.kind && 'label' !== item.kind && 'tabIndex' !== item.kind && 'enabled' !== item.kind && 'calcOnExit' !== item.kind && 'entryMacro' !== item.kind && 'exitMacro' !== item.kind && 'helpText' !== item.kind && 'statusText' !== item.kind && 'checkBox' !== item.kind && 'ddList' !== item.kind && 'textInput' !== item.kind) issues.push(issue(path + '.content[' + i + ']', 'invalid-value', 'unknown choice alternative'));
        }
      }
    }
  }
  return issues;
}

